class SocketProbe { public static void main(String[] a) throws Exception { try(var s=new java.net.ServerSocket(0,1,java.net.InetAddress.getByName("127.0.0.1"))){ System.out.println("bound "+s.getLocalPort()); var t=new Thread(()->{try(var c=s.accept()){System.out.println("accepted");}catch(Exception e){e.printStackTrace();}});t.start(); try(var c=new java.net.Socket("127.0.0.1",s.getLocalPort())){System.out.println("connected");}t.join(3000); } } }
